<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/bootstrap.php';
$user = require_login();
if (($user['role'] ?? '') !== 'lecturer') { http_response_code(403); exit('Lecturer access required.'); }
$pdo = db();
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT, ['options'=>['min_range'=>1]]);
if (!$id) { http_response_code(400); exit('Invalid teaching group.'); }
$q = $pdo->prepare('SELECT lda.id, lda.degree_id, lda.batch_id, lda.study_year, lda.semester, d.name AS degree_name, b.batch_code FROM lecturer_degree_assignments lda JOIN lecturer_profiles lp ON lp.id=lda.lecturer_id JOIN academic_degrees d ON d.id=lda.degree_id JOIN academic_batches b ON b.id=lda.batch_id WHERE lda.id=? AND lp.user_id=? AND lp.is_active=1 AND lda.is_active=1 LIMIT 1');
$q->execute([$id, (int)$user['id']]);
$group = $q->fetch(PDO::FETCH_ASSOC);
if (!$group) { http_response_code(404); exit('Teaching group not found or access denied.'); }
// A programme-level teaching group does not itself grant permission to manage its modules.
// Show only modules explicitly assigned to this lecturer.
$q = $pdo->prepare('SELECT DISTINCT m.module_code,m.module_name,c.study_year,c.semester FROM lecturer_module_assignments a JOIN lecturer_profiles lp ON lp.id=a.lecturer_id JOIN academic_curriculum c ON c.id=a.curriculum_id JOIN academic_modules m ON m.id=c.module_id WHERE lp.user_id=? AND lp.is_active=1 AND a.is_active=1 AND c.is_active=1 AND m.is_active=1 AND c.degree_id=? AND c.batch_id=? AND c.study_year=? AND (?=0 OR c.semester=?) ORDER BY c.semester,m.module_name');
$q->execute([(int)$user['id'],(int)$group['degree_id'],(int)$group['batch_id'],(int)$group['study_year'],(int)$group['semester'],(int)$group['semester']]);
$modules=$q->fetchAll(PDO::FETCH_ASSOC);
// Student records are taken from the canonical academic profile and current progression.
$q=$pdo->prepare("SELECT u.full_name, u.student_number FROM student_academic_profiles p JOIN users u ON u.id=p.user_id LEFT JOIN academic_intake_progression ap ON ap.degree_id=p.degree_id AND ap.batch_id=p.batch_id WHERE u.role='student' AND p.degree_id=? AND p.batch_id=? AND ap.study_year=? AND (?=0 OR ap.semester=?) ORDER BY u.full_name");
$q->execute([(int)$group['degree_id'],(int)$group['batch_id'],(int)$group['study_year'],(int)$group['semester'],(int)$group['semester']]);
$students=$q->fetchAll(PDO::FETCH_ASSOC);
$theme=(string)($user['theme']??'system');
$tab=(string)($_GET['tab']??'overview');
if(!in_array($tab,['overview','modules','students'],true))$tab='overview';
$base=url('lecturer/teaching-group.php').'?id='.(int)$group['id'];
?>
